(()=>{const n=document.getElementById("site-search-query"),s=document.getElementById("site-search-results"),e=document.getElementById("site-search-status");if(!n||!s||!e)return;let o=[];const t=e=>String(e).replace(/[&<>"']/g,e=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#039;"}[e])),i=document.currentScript,a=i?i.dataset.indexUrl:"index.json";fetch(a).then(e=>e.json()).then(e=>{o=e,n.addEventListener("input",()=>r(n.value))}).catch(()=>{e.textContent="Search is currently unavailable."});function r(n){const a=n.trim().toLowerCase();if(!a){s.innerHTML="",e.textContent="Type to search all posts.";return}const i=o.filter(e=>[e.title,e.summary,e.content,...e.tags||[]].join(" ").toLowerCase().includes(a));e.textContent=`${i.length} result${i.length===1?"":"s"} found.`,s.innerHTML=i.map(e=>`<article class="rounded-md border border-neutral-200 p-5 dark:border-neutral-700"><h2 class="text-2xl font-bold"><a href="${t(e.permalink)}" class="hover:underline">${t(e.title)}</a></h2><p class="mt-2 text-sm text-neutral-500">${t((e.tags||[]).join(" · "))}</p><p class="mt-3">${t(e.summary||"")}</p></article>`).join("")||"<p>No posts matched your search.</p>"}})()